import{_ as s,o as e,c as i,a0 as t}from"./chunks/framework.ZHwfgYkM.js";const k=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md","lastUpdated":null}'),n={name:"troubleshooting.md"};function l(o,a,r,h,p,c){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="快速定位" tabindex="-1">快速定位 <a class="header-anchor" href="#快速定位" aria-label="Permalink to &quot;快速定位&quot;">​</a></h2><p>先判斷是哪一類問題：</p><ol><li>Build / 測試失敗</li><li>UI 渲染或路由問題</li><li>部署後行為與本機不同</li></ol><h2 id="a-release-sync-check-失敗" tabindex="-1">A. <code>release:sync-check</code> 失敗 <a class="header-anchor" href="#a-release-sync-check-失敗" aria-label="Permalink to &quot;A. `release:sync-check` 失敗&quot;">​</a></h2><p><strong>症狀</strong>：CI 指出版本與 tag 不一致。<br><strong>處理</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release:sync-check</span></span></code></pre></div><p>然後回到標準 release 流程，不要手動改 tag/version。</p><h2 id="b-ui-看起來正常-但-e2e-失敗" tabindex="-1">B. UI 看起來正常，但 E2E 失敗 <a class="header-anchor" href="#b-ui-看起來正常-但-e2e-失敗" aria-label="Permalink to &quot;B. UI 看起來正常，但 E2E 失敗&quot;">​</a></h2><p><strong>先跑</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright:ui-layout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend</span></span></code></pre></div><p>再補功能測試（例如 bank/carrier sync）。</p><h2 id="c-原生依賴或-runtime-行為不一致" tabindex="-1">C. 原生依賴或 runtime 行為不一致 <a class="header-anchor" href="#c-原生依賴或-runtime-行為不一致" aria-label="Permalink to &quot;C. 原生依賴或 runtime 行為不一致&quot;">​</a></h2><p>若問題落在後端 native 相依（例如 sqlite binding），請優先依部署 runbook 檢查 container 內安裝流程，而非只重跑表面指令。</p><div class="tip custom-block"><p class="custom-block-title">排查順序</p><p>先重現 -&gt; 確認分類 -&gt; 跑最小驗證指令 -&gt; 再改動。<br> 這樣可以避免一次改太多造成新回歸。</p></div>',15)])])}const u=s(n,[["render",l]]);export{k as __pageData,u as default};
